type ServiceView = { readonly balance: number; charge(id: string): Receipt };

function membrane(target: Service): ServiceView {
  return Object.defineProperty({ charge: target.charge.bind(target) }, "balance", {
    enumerable: true,
    get: () => target.balance,
  }) as ServiceView;
}
